#!/usr/bin/env bash
set -euo pipefail
python3 - <<'PYTHON'
from pathlib import Path
import base64,gzip,json,re,datetime,os,shutil,subprocess,time,urllib.request
assert os.geteuid()==0,'Run from the BaoTa root terminal'
service=Path('/etc/systemd/system/warlords2-coop.service').read_text()
roots=set(re.findall(r'/opt/warlords2/releases/[^/\s";]+',service))
assert len(roots)==1,'Cannot identify active release'
root=Path(next(iter(roots)));game=root/'种族战役2复刻'
assert any(v in (game/'coop-local-server.cjs').read_text() for v in ['0.10.3-native-weapons','0.10.4-coop-net']),'Unexpected installed version'
files=json.loads(gzip.decompress(base64.b64decode('')))
backup=Path('/opt/warlords2/backups')/('net-scythe-fix-'+datetime.datetime.now().strftime('%Y%m%d-%H%M%S'))
backup.mkdir(parents=True)
existing=[]
for name in files:
 p=root/name
 if p.exists():
  dest=backup/name;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dest);existing.append(name)
(backup/'manifest.json').write_text(json.dumps({'root':str(root),'existing':existing,'files':list(files)},ensure_ascii=False),encoding='utf-8')
rollback='#!/usr/bin/env bash\nset -euo pipefail\n'+''.join('cp -a "'+str(backup/n)+'" "'+str(root/n)+'"\n' for n in existing)+'systemctl restart warlords2-coop.service\n'
(backup/'rollback.sh').write_text(rollback,encoding='utf-8')
restarted=False
try:
 for name,content in files.items():
  p=root/name;p.parent.mkdir(parents=True,exist_ok=True);tmp=p.with_name(p.name+'.netfix.tmp');tmp.write_text(content,encoding='utf-8');tmp.chmod(0o644);os.replace(tmp,p)
 node='/opt/warlords2/node-v24.21.0-linux-x64/bin/node'
 for test in ['种族战役2复刻/coop-loading-tests.cjs','种族战役2复刻/scythe-regression-tests.cjs','合作模式预研/compression-tests.cjs']:
  subprocess.run([node,str(root/test)],cwd=root,check=True,timeout=60)
 restarted=True
 subprocess.run(['systemctl','restart','warlords2-coop.service'],check=True,timeout=30)
 health=None
 for i in range(20):
  try:
   with urllib.request.urlopen('http://127.0.0.1:18643/warlords2/coop-health',timeout=3) as r: health=json.load(r)
   if health.get('release')=='0.10.4-coop-net':break
  except Exception:pass
  time.sleep(1)
 assert health and health.get('release')=='0.10.4-coop-net','New service did not become healthy'
except Exception:
 for name in existing:shutil.copy2(backup/name,root/name)
 if restarted:subprocess.run(['systemctl','restart','warlords2-coop.service'],check=True,timeout=30)
 print('PATCH_FAILED: previous files restored; backup:',backup)
 raise
print('NET_FIX_OK version=0.10.4-coop-net')
print('Rollback: bash '+str(backup/'rollback.sh'))
print('Both players: Ctrl+F5, then create a new room.')
PYTHON
